// Verify the Google ID token server-side (keyless tokeninfo endpoint).
// Contract: doc/MULTITENANT.md section 4.1.
// n8n 2.x delivers the parsed request body under $json.body; the Code-node
// sandbox has no global fetch, so use https (allowed via NODE_FUNCTION_ALLOW_BUILTIN).
const https = require('https');

function getJson(url) {
  return new Promise((resolve, reject) => {
    https.get(url, (res) => {
      let data = '';
      res.on('data', (c) => { data += c; });
      res.on('end', () => {
        try { resolve({ status: res.statusCode, body: JSON.parse(data) }); }
        catch (e) { reject(new Error('tokeninfo returned non-JSON')); }
      });
    }).on('error', reject);
  });
}

const payload = ($input.first().json || {}).body || {};
const idToken = payload.idToken ? String(payload.idToken).trim() : '';
if (!idToken) {
  return [{ json: { ok: false, statusCode: 400, error: 'AUTH_MISSING_IDTOKEN: body.idToken is required' } }];
}
const { status, body: info } = await getJson(
  `https://oauth2.googleapis.com/tokeninfo?id_token=${encodeURIComponent(idToken)}`
);
if (status !== 200 || info.error) {
  return [{ json: {
    ok: false,
    statusCode: 401,
    error: 'AUTH_INVALID_IDTOKEN: ' + (info.error_description || info.error || status),
  } }];
}
// tokeninfo returns email_verified as the string "true".
const verified = info.email_verified === true || info.email_verified === 'true';
if (!verified) {
  return [{ json: { ok: false, statusCode: 401, error: 'AUTH_EMAIL_NOT_VERIFIED' } }];
}
return [{ json: {
  ok: true,
  google_sub: String(info.sub),
  email: String(info.email || '').toLowerCase(),
  name: String(info.name || '').trim(),
} }];

// Issue the HMAC session token (v1.<payload>.<sig>).
// Payload: { uid, exp } — 30 day expiry. Secret: AUTH_TOKEN_SECRET (n8n env).
const crypto = require('crypto');
const row = $input.first().json;
const secret = $env.AUTH_TOKEN_SECRET;
if (!secret) {
  return [{ json: { ok: false, statusCode: 500, error: 'AUTH_SECRET_NOT_CONFIGURED' } }];
}
const exp = Math.floor(Date.now() / 1000) + (60 * 60 * 24 * 30);
const payload = Buffer.from(JSON.stringify({ uid: row.id, exp })).toString('base64url');
const sig = crypto.createHmac('sha256', secret).update(payload).digest('base64url');
return [{ json: {
  token: `v1.${payload}.${sig}`,
  user: {
    id: row.id,
    name: row.name,
    email: row.email,
    company_id: row.company_id,
    setup_complete: !!row.setup_complete,
  },
} }];
